:root{color-scheme:dark;--bg:#090812;--panel:#121020;--line:#29243d;--text:#f6f3ff;--muted:#aaa3bd;--purple:#9b72ff}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:15px Inter,system-ui,sans-serif}main{max-width:1050px;margin:45px auto;padding:0 22px}a{color:#c6b1ff;text-decoration:none}.panel{background:var(--panel);border:1px solid var(--line);border-radius:16px;padding:22px;margin:18px 0}.muted{color:var(--muted);font-size:13px}.metric{font-size:38px;font-weight:900;margin:12px 0}.bars{height:190px;display:flex;align-items:end;gap:5px;border-bottom:1px solid var(--line);padding-top:20px}.bar{flex:1;min-width:3px;background:linear-gradient(0deg,#7144e8,#b69aff);border-radius:5px 5px 0 0;position:relative}.bar:hover:after{content:attr(data-tip);position:absolute;bottom:100%;left:50%;transform:translateX(-50%);background:#29213e;padding:5px;border-radius:5px;font-size:11px;white-space:nowrap}.row{display:grid;grid-template-columns:1fr auto auto;gap:16px;padding:13px 0;border-top:1px solid var(--line)}@media(max-width:600px){.row{grid-template-columns:1fr auto}.row span:last-child{display:none}}
